contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: we call Initialized(), then attempt SetMinSum and SetLogFile and assert both revert
    function run(uint someMin, address someLog) public payable {
        // Ensure we start from fresh interaction: call Initialized() (state-changing, top-level)
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Try SetMinSum after initialization and record whether it reverted
        bool setMinReverted;
        c.SetMinSum(someMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }

        // Try SetLogFile after initialization and record whether it reverted
        bool setLogReverted;
        c.SetLogFile(someLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
        }

        // General rule: after Initialized() both setters must revert
        assert(setMinReverted && setLogReverted);
    }

    receive() external payable { }
}

