pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 someMin, address someLog) internal {
        try c.Initialized() {} catch { return; }
        bool setMinReverted;
        try c.SetMinSum(someMin) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }
        bool setLogReverted;
        try c.SetLogFile(someLog) {
            setLogReverted = false;
        } catch {
            setLogReverted = true;
        }
        assertTrue(setMinReverted && setLogReverted);
    }

    function testFuzz_run(uint256 someMin, address someLog) public {
        vm.assume(someLog.code.length == 0 && uint160(someLog) > 0xffff && someLog != address(this) && someLog != address(c) && someLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && someLog != 0x000000000000000000636F6e736F6c652e6c6f67 && someLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && someLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(someMin, someLog);
    }

    receive() external payable { }
}
